update ujcms_page_region
set layout_json_ = #{bean.layoutJson,jdbcType=OTHER},
  draft_layout_json_ = #{bean.draftLayoutJson,jdbcType=OTHER},
  version_ = version_ + 1,
  modified_ = #{bean.modified,jdbcType=TIMESTAMP}
where id_ = #{bean.id,jdbcType=BIGINT} and version_ = #{version,jdbcType=INTEGER}

mapper.select:
select

from ujcms_page_region t
where t.id_ = #{id,jdbcType=BIGINT}

select

from ujcms_page_region t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.page_ref_ = #{pageRef,jdbcType=VARCHAR}
  and t.region_name_ = #{regionName,jdbcType=VARCHAR}
  and t.scope_ = #{scope,jdbcType=VARCHAR}

select

from ujcms_page_region t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.page_ref_ = #{pageRef,jdbcType=VARCHAR}
  and t.region_name_ = #{regionName,jdbcType=VARCHAR}
order by case when t.scope_ = 'default' then 0 else 1 end, t.scope_

select distinct t.scope_
from ujcms_page_region t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.page_ref_ = #{pageRef,jdbcType=VARCHAR}
  and t.scope_ != 'default'
order by t.scope_

select

from ujcms_page_region t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.origin_ = #{origin,jdbcType=VARCHAR}
order by t.id_

select count(*)
from ujcms_page_region t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.origin_ = #{origin,jdbcType=VARCHAR}

