update ujcms_page_region
set origin_ = null, origin_hash_ = null
where site_id_ = #{siteId,jdbcType=BIGINT}
  and origin_ = #{origin,jdbcType=VARCHAR}

update ujcms_page_region
set origin_hash_ = #{originHash,jdbcType=CHAR}
where id_ = #{id,jdbcType=BIGINT}

update ujcms_page_region
set origin_ = #{origin,jdbcType=VARCHAR}
where id_ = #{id,jdbcType=BIGINT}

update ujcms_page_region
set origin_ = #{origin,jdbcType=VARCHAR},
    origin_hash_ = #{originHash,jdbcType=CHAR}
where id_ = #{id,jdbcType=BIGINT}
  and (origin_ is null or origin_ = '')
